-- Volledige inktcontrole 2026-10-09. Exacte productidentiteit geverifieerd via actuele producttitel en bestelknop.
-- 32 zoeklinks hersteld, 36 HP 415X-referenties geharmoniseerd, 1 HP 303-doublepack gecorrigeerd.
-- Prijzen, eenheden, printerkoppelingen en actief-status blijven behouden. Geen bestellingen wijzigen.
begin;
create temporary table ink_fix(id bigint,naam text,old_article text,old_url text,article text,url text) on commit drop;
create temporary table ink_before on commit drop as select id,to_jsonb(c)-'artikelnummer'-'leverancier_url'-'updated_at' as value from public.aankoop_printer_cartridges c where id in(select id from ink_fix);
do $fix$
declare n integer;
begin
 update public.aankoop_printer_cartridges c set artikelnummer=f.article,leverancier_url=f.url
 from ink_fix f where c.id=f.id and c.naam=f.naam and c.artikelnummer=f.old_article and c.leverancier_url=f.old_url and c.leverancier='123inkt.be';
 get diagnostics n=row_count;
 if n<>69 then raise exception 'Catalogus gewijzigd: verwacht 69 vermeldingen, gevonden %',n; end if;
 if exists(select 1 from ink_before b join public.aankoop_printer_cartridges c using(id) where b.value<>to_jsonb(c)-'artikelnummer'-'leverancier_url'-'updated_at') then raise exception 'Onbedoelde wijziging'; end if;
end $fix$;
commit;
